interactions.sample_code:
function relax(u, v, w) {
  const du = dist(u);
  if (du === Infinity) {
    mark(u, v, "source still unreachable");
    return;
  }

  const candidate = du + w;
  if (less(candidate, dist(v))) {
    mark(u, v, "relaxed: " + candidate + " < " + dist(v));
    setDist(v, candidate);
    setPred(v, u);
  } else {
    mark(u, v, "no change");
  }
}

